mapper.select:
SELECT TU.SEQ, TU.USER_ID, TU.NAME, TU.MOBILE, TU.EMAIL , TU.AUTH_SEQ, TA.NAME AS AUTH_NAME , TU.PASSWORD_RESET, TU.LAST_LOGIN_DATETIME , TU.CREATE_DATETIME, TU.CREATE_IDX , TU.UPDATE_DATETIME, TU.UPDATE_IDX FROM TB_USER TU LEFT OUTER JOIN TB_AUTH TA ON TA.SEQ = TU.AUTH_SEQ WHERE 1 = 1 AND TU.DELETED = 0
AND TU.USER_ID LIKE CONCAT('%', #{searchValue}, '%')
ORDER BY TU.USER_ID LIMIT #{startDataNumber}, #{dataCount}

mapper.insert:
INSERT INTO TB_USER 
(
  USER_ID, PASSWORD
  , CREATE_DATETIME, CREATE_IDX
)
VALUES 
(
  #{userId}, #{password}
  , NOW(), #{createIdx}
)

mapper.update:
UPDATE TB_USER
SET UPDATE_DATETIME = NOW()
  , UPDATE_IDX = #{createIdx}

  , NAME = #{name}


  , PASSWORD = #{password}


  , AUTH_SEQ = #{authSeq}


  , MOBILE = #{mobile}


  , EMAIL = #{email}

WHERE SEQ = #{seq}

UPDATE TB_USER
SET DELETED = 1
  , DELETE_DATETIME = NOW()
  , DELETE_IDX = #{createIdx}
WHERE SEQ = #{seq}

UPDATE TB_USER
SET PASSWORD_RESET = 1
WHERE SEQ = #{seq}

UPDATE TB_USER
SET LAST_LOGIN_DATETIME = NOW()
WHERE SEQ = #{seq}
